"use strict";(self.webpackChunk_abdm_docs_site=self.webpackChunk_abdm_docs_site||[]).push([["37237"],{33876(e,t,i){i.r(t),i.d(t,{metadata:()=>a,default:()=>u,frontMatter:()=>p,contentTitle:()=>c,toc:()=>h,assets:()=>d});var a=JSON.parse('{"id":"nhcx/v1/api/registry/endpoints/registry-v2-participant-get-policies","title":"Get beneficiary policies (V2)","description":"V2 variant of the beneficiary policy lookup; same FetchParticipantPoliciesRequest body and ParticipantListResponse as the unversioned call.","source":"@site/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-get-policies.mdx","sourceDirName":"nhcx/v1/api/registry/endpoints","slug":"/nhcx/v1/api/registry/endpoints/registry-v2-participant-get-policies","permalink":"/docs/pr-18/docs/nhcx/v1/api/registry/endpoints/registry-v2-participant-get-policies","draft":false,"unlisted":false,"tags":[],"version":"current","lastUpdatedAt":null,"frontMatter":{"title":"Get beneficiary policies (V2)","sidebar_label":"Get beneficiary policies (V2)","sidebar_class_name":"api-method api-method--post","description":"V2 variant of the beneficiary policy lookup; same FetchParticipantPoliciesRequest body and ParticipantListResponse as the unversioned call.","hide_table_of_contents":true,"hide_title":true,"wrapperClassName":"api-doc","source":"nhcx-registry.yaml","generated":true},"sidebar":"nhcx-v1-api","previous":{"title":"Get beneficiary policies","permalink":"/docs/pr-18/docs/nhcx/v1/api/registry/endpoints/registry-participant-get-policies"},"next":{"title":"Update ABHA number","permalink":"/docs/pr-18/docs/nhcx/v1/api/registry/endpoints/registry-update-abhanumber"}}'),n=i(62540),r=i(43023),s=i(75064),o=JSON.parse('{"id":"registry_v2_participant_get_policies","module":"Participant registry","moduleId":"registry","kind":"operation","method":"POST","path":"/V2/participant/get/policies","server":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","servers":[{"url":"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice","description":"Sandbox, Participant service."},{"url":"https://apisprod.nha.gov.in/pmjay/hcx/participanthcxservice","description":"Production."}],"summary":"Get beneficiary policies (V2)","title":"Get beneficiary policies (V2)","description":"V2 variant of the beneficiary policy lookup; same FetchParticipantPoliciesRequest body and ParticipantListResponse as the unversioned call.\\n\\n### Business purpose\\n\\nThis endpoint answers the same question as /participant/get/policies: which payer products is this beneficiary linked to, and therefore which payer or TPA should the hospital address. The OpenAPI document exposes it as getParticipantGetPoliciesV2 with an identical request and response schema and the same Registry APIs tag; the documentation records no behavioural difference beyond the path. Integrations that use the V2 link and de-link calls typically read back through this endpoint.\\n\\n### When to use\\n\\nUse it at the same point in the journey as the v1 lookup: after registration, before InsurancePlan retrieval, coverage eligibility and preauthorisation (workflow code 12), and whenever a cached policy needs to be re-validated with forceRefresh. Payers and TPAs use it to confirm a link or de-link they have just written. Pick one of the two get-policies paths and use it consistently.\\n\\n### Preconditions\\n\\n- A valid Bearer token from the client-credentials call (POST /get/session, form-urlencoded client_ID, client_secret, grant_type=client_credentials); tokens last 1200 seconds, so refresh before expiry.\\n- HTTP headers Accept: application/json, Content-Type: application/json and bearer_auth: Bearer <token> (the participant service uses bearer_auth, not Authorisation).\\n- Base path for the participant service: https://apisbx.ABDM.gov.in/pmjay/sbxhcx/participanthcxservice (sandbox) or https://apisprod.NHA.gov.in/pmjay/hcx/participanthcxservice (production).\\n- This is a synchronous plain-JSON registry call: no JWE envelope, no x-hcx-* protocol headers and no correlation ID are involved.\\n- A payer or TPA must already have linked the beneficiary.\\n- Body: identifiertype (AbhaNumber, MemberId or MobileNo) and identifiervalue, both required; ABHA without hyphens.\\n- Note the capital V in /V2/.\\n\\n### Postconditions\\n\\nReturns HTTP 200 with ParticipantListResponse (optional participantdetails array of participantcode, participantname, address, state). No callback follows. The result is normalised and cached by the caller; the handbook documents that cache as permanent until forceRefresh: true is passed. The processingID from the response is the receiver code for NHCX routing, and payerId, memberId, productId, productName and policyNumber are resolved from the cached policies for the preauth. Errors return 400, 404 or 500 with the ErrorResponse envelope.\\n\\n### Common mistakes\\n\\n- Sending the ABHA number with hyphens; the identifier table specifies ABHA without hyphens for this lookup and a hyphenated value is a common cause of an empty result.\\n- Using the PayerID from the response as x-hcx-recipient_code; NHA\'s common mistake 7 says providers must use the processingID from the get/Policies response as the receiver code, otherwise NHCX-1003 (receiver not registered) or PAYR-1331 follows.\\n- Trying only one identifier type; the handbook prescribes a cascade of AbhaNumber, then MemberId, then MobileNo.\\n- Dereferencing fields blindly; every field of ParticipantDetails is optional and the response shape may arrive as participantdetails, participants or a raw array.\\n- Trusting a permanent policy cache after a payer-side change instead of passing forceRefresh: true.\\n- Lower-casing the path to /v2/participant/get/policies, which is not a documented route.\\n\\n### Best practices\\n\\n- Normalise the ABHA number (strip separators) before the call and try identifiers in the documented priority order: ABHA, then MemberId from the latest admission, then mobile number.\\n- Cache successful lookups keyed by patient, but expose a forceRefresh path and use it as the first diagnostic step when a preauth is rejected for a coverage mismatch.\\n- Store payerId, memberId, productId, productName and policyNumber from the result; these feed x-hcx-recipient_code, the Coverage and Patient identifiers and the InsurancePlan lookup.\\n- If the lookup yields nothing, fall back to a coverage-eligibility check with purpose discovery to obtain the active policy code.\\n- Keep the token fresh; retry once on 401.\\n\\n### Related scenario\\n\\nA TPA has just linked a new member through /V2/participant/link/abha/policy and wants to verify the write before closing the ticket. It calls /V2/participant/get/policies with identifiertype AbhaNumber and the member\'s hyphen-free ABHA number and sees the product returned. Months later the same member is admitted; the hospital\'s HMIS runs the identifier cascade (ABHA, then member ID, then mobile) against this endpoint, caches the result, and proceeds to /v1/insuranceplan/request and /v1/preauth/submit addressed to the TPA\'s participant code taken from processingID.\\n\\n### Specification\\n\\nChapter [Creating and updating a participant](/docs/nhcx/v1/getting-started/creating-and-updating-a-participant) of the NHCX integration specification.","security":[{"name":"bearerAuth","type":"http","scheme":"bearer","description":"On every NHCX call, the token goes in a header called `bearer_auth`, with the word `Bearer` and a space in front. The sources are not unanimous: the authentication page and the FAQ both write the example as `Authorization`, and the notification endpoint uses `Authorization`. The safe course, and what the adapter does, is to send both headers with the same value."}],"headers":[{"name":"bearer_auth","required":true,"description":"It is `bearer_auth`, not `Authorization`, on NHCX\'s own endpoints.","example":"Bearer <access token>","type":"string"}],"pathParams":[],"queryParams":[],"body":[{"name":"identifiertype","type":"string","required":false,"description":"","encrypted":false},{"name":"identifiervalue","type":"string","required":false,"description":"","encrypted":false}],"requestExample":{"identifiertype":"MemberId","identifiervalue":"MEM-2026-000123"},"responses":[{"status":"200","description":"Returns HTTP 200 with ParticipantListResponse (optional participantdetails array of participantcode, participantname, address, state).","example":{"participantdetails":[{"participantcode":"100234@sbx","participantname":"Demo Health Insurance Co","address":"Plot 12, Sector 5, Gurugram","state":"Haryana"}]}}],"tag":"Other operations","curl":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/V2/participant/get/policies \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"identifiertype\\": \\"MemberId\\",\\n  \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n}\'","samples":[{"id":"curl","label":"cURL","language":"bash","code":"curl --request POST \\\\\\n  --url https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/V2/participant/get/policies \\\\\\n  --header \'Authorization: Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\' \\\\\\n  --header \'bearer_auth: Bearer <access token>\' \\\\\\n  --header \'Content-Type: application/json\' \\\\\\n  --data \'{\\n  \\"identifiertype\\": \\"MemberId\\",\\n  \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n}\'"},{"id":"python","label":"Python","language":"python","code":"import requests\\n\\nresponse = requests.post(\\n    \\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/V2/participant/get/policies\\",\\n    headers={\\n        \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n        \\"bearer_auth\\": \\"Bearer <access token>\\",\\n        \\"Content-Type\\": \\"application/json\\",\\n    },\\n    json={\\n        \\"identifiertype\\": \\"MemberId\\",\\n        \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n    },\\n)\\n\\nprint(response.status_code, response.text)"},{"id":"node","label":"Node","language":"javascript","code":"const response = await fetch(\\"https://apisbx.abdm.gov.in/pmjay/sbxhcx/participanthcxservice/V2/participant/get/policies\\", {\\n  method: \\"POST\\",\\n  headers: {\\n    \\"Authorization\\": \\"Bearer <ACCESS_TOKEN_FROM_SESSIONS_CALL>\\",\\n    \\"bearer_auth\\": \\"Bearer <access token>\\",\\n    \\"Content-Type\\": \\"application/json\\",\\n  },\\n  body: JSON.stringify({\\n    \\"identifiertype\\": \\"MemberId\\",\\n    \\"identifiervalue\\": \\"MEM-2026-000123\\"\\n  }),\\n});\\n\\nconsole.log(response.status, await response.text());"}]}');let p={title:"Get beneficiary policies (V2)",sidebar_label:"Get beneficiary policies (V2)",sidebar_class_name:"api-method api-method--post",description:"V2 variant of the beneficiary policy lookup; same FetchParticipantPoliciesRequest body and ParticipantListResponse as the unversioned call.",hide_table_of_contents:!0,hide_title:!0,wrapperClassName:"api-doc",source:"nhcx-registry.yaml",generated:!0},c,d={},h=[];function l(e){return(0,n.jsx)(s.A,{operation:o})}function u(e={}){let{wrapper:t}={...(0,r.R)(),...e.components};return t?(0,n.jsx)(t,{...e,children:(0,n.jsx)(l,{...e})}):l(e)}}}]);